// ── Sheet A  →  Sheet B (Odoo import format) ──────────────────────────
// Each `row` below is ONE line from the uploaded orders sheet (Sheet A).
//
// EDIT THIS MAPPING:
//   • The keys on the LEFT  = the EXACT column headers Odoo expects (Sheet B).
//   • The values on the RIGHT = the column names in YOUR uploaded sheet (Sheet A),
//     written as  row["Your Column Name"].
//
// Add, remove, or rename lines to match your real sheets.

return $input.all().map((item) => {
  const row = item.json;
  return {
    json: {
      // Odoo column (Sheet B)  :  value taken from your orders sheet (Sheet A)
      "order_ref"   : row["Order ID"],
      "partner_id"  : row["Customer Name"],
      "product_name": row["Product"],
      "product_qty" : row["Qty"],
      "price_unit"  : row["Unit Price"],
      "date_order"  : row["Order Date"],
    },
  };
});
